Read file C:\Users\Administrator\Desktop\新建文件夹\1.html, lines 1-849
1: <!DOCTYPE html>
2: <html lang="zh-CN">
3: <head>
4: <meta charset="UTF-8">
5: <meta name="viewport" content="width=device-width, initial-scale=1.0">
6: <title>教师端 - 课堂辅助系统</title>
7: <link rel="icon" href="data:image/svg+xml,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 100 100'><text y='.9em' font-size='90'>📚</text></svg>">
8: <meta http-equiv="Cache-Control" content="no-cache, no-store, must-revalidate">
9: <meta http-equiv="Pragma" content="no-cache">
10: <meta http-equiv="Expires" content="0">
11: <style>
12: /* ═══════════════════════════════════════════════
13:    全局 & 布局
14: ═══════════════════════════════════════════════ */
15: *{margin:0;padding:0;box-sizing:border-box;}
16: :root{
17:   --primary:#1565c0;--primary-light:#1e88e5;--primary-dark:#0d47a1;
18:   --success:#2e7d32;--warning:#f57f17;--danger:#c62828;--info:#00838f;
19:   --bg:#f0f4f8;--sidebar-bg:#0d47a1;--white:#fff;
20:   --text:#212121;--text-light:#757575;--border:#e0e0e0;
21:   --shadow:0 2px 12px rgba(0,0,0,.08);
22:   --radius:10px;
23: }
24: body{font-family:'Microsoft YaHei',sans-serif;background:var(--bg);color:var(--text);display:flex;height:100vh;overflow:hidden;}
25: 
26: /* ─── 侧边栏 ─── */
27: .sidebar{width:220px;min-width:220px;background:var(--sidebar-bg);display:flex;flex-direction:column;overflow-y:auto;}
28: .sidebar-logo{padding:24px 20px;border-bottom:1px solid rgba(255,255,255,.1);}
29: .sidebar-logo h2{color:#fff;font-size:1.1rem;font-weight:700;letter-spacing:1px;}
30: .sidebar-logo p{color:rgba(255,255,255,.5);font-size:.75rem;margin-top:4px;}
31: .nav-item{display:flex;align-items:center;gap:12px;padding:14px 20px;color:rgba(255,255,255,.7);cursor:pointer;transition:all .2s;font-size:.9rem;}
32: .nav-item:hover{background:rgba(255,255,255,.1);color:#fff;}
33: .nav-item.active{background:rgba(255,255,255,.15);color:#fff;border-left:3px solid #90caf9;}
34: .nav-item .icon{font-size:1.2rem;width:24px;text-align:center;}
35: .nav-sep{height:1px;background:rgba(255,255,255,.1);margin:8px 0;}
36: .back-home{margin-top:auto;padding:16px 20px;border-top:1px solid rgba(255,255,255,.1);}
37: .back-home a{color:rgba(255,255,255,.6);text-decoration:none;font-size:.85rem;display:flex;align-items:center;gap:8px;}
38: .back-home a:hover{color:#fff;}
39: 
40: /* ─── 主内容区 ─── */
41: .main{flex:1;display:flex;flex-direction:column;overflow:hidden;}
42: .topbar{background:var(--white);padding:16px 28px;display:flex;align-items:center;justify-content:space-between;box-shadow:0 1px 4px rgba(0,0,0,.08);}
43: .topbar h1{font-size:1.2rem;font-weight:700;color:var(--primary-dark);}
44: .topbar-right{display:flex;align-items:center;gap:12px;}
45: .content{flex:1;padding:24px 28px;overflow-y:auto;}
46: 
47: /* ─── 卡片 ─── */
48: .card{background:var(--white);border-radius:var(--radius);padding:24px;box-shadow:var(--shadow);margin-bottom:20px;}
49: .card-title{font-size:1.05rem;font-weight:700;color:var(--primary-dark);margin-bottom:16px;display:flex;align-items:center;gap:8px;}
50: .grid-2{display:grid;grid-template-columns:1fr 1fr;gap:20px;}
51: .grid-3{display:grid;grid-template-columns:1fr 1fr 1fr;gap:16px;}
52: .grid-4{display:grid;grid-template-columns:repeat(4,1fr);gap:16px;}
53: 
54: /* ─── 统计卡 ─── */
55: .stat-card{background:linear-gradient(135deg,var(--primary),var(--primary-light));color:#fff;border-radius:var(--radius);padding:20px 24px;}
56: .stat-card.green{background:linear-gradient(135deg,#2e7d32,#43a047);}
57: .stat-card.orange{background:linear-gradient(135deg,#e65100,#f57c00);}
58: .stat-card.teal{background:linear-gradient(135deg,#006064,#00838f);}
59: .stat-card .num{font-size:2rem;font-weight:700;line-height:1;}
60: .stat-card .label{font-size:.85rem;opacity:.85;margin-top:6px;}
61: 
62: /* ─── 按钮 ─── */
63: .btn{padding:8px 20px;border:none;border-radius:6px;cursor:pointer;font-size:.88rem;font-family:inherit;font-weight:500;transition:all .2s;display:inline-flex;align-items:center;gap:6px;}
64: .btn-primary{background:var(--primary);color:#fff;}
65: .btn-primary:hover{background:var(--primary-dark);}
66: .btn-success{background:var(--success);color:#fff;}
67: .btn-success:hover{background:#1b5e20;}
68: .btn-danger{background:var(--danger);color:#fff;}
69: .btn-danger:hover{background:#b71c1c;}
70: .btn-warning{background:#f57f17;color:#fff;}
71: .btn-warning:hover{background:#e65100;}
72: .btn-secondary{background:#607d8b;color:#fff;}
73: .btn-secondary:hover{background:#455a64;}
74: .btn-outline{background:transparent;border:1px solid var(--border);color:var(--text);}
75: .btn-outline:hover{border-color:var(--primary);color:var(--primary);}
76: .btn-sm{padding:5px 12px;font-size:.8rem;}
77: .btn-xs{padding:3px 8px;font-size:.75rem;}
78: 
79: /* ─── 表单 ─── */
80: .form-row{display:flex;gap:12px;margin-bottom:12px;flex-wrap:wrap;}
81: .form-group{display:flex;flex-direction:column;gap:4px;flex:1;min-width:120px;}
82: .form-group label{font-size:.82rem;color:var(--text-light);font-weight:500;}
83: .form-control{padding:8px 12px;border:1px solid var(--border);border-radius:6px;font-size:.88rem;font-family:inherit;outline:none;transition:border .2s;background:#fff;}
84: .form-control:focus{border-color:var(--primary);}
85: select.form-control{cursor:pointer;}
86: textarea.form-control{resize:vertical;min-height:80px;}
87: 
88: /* ─── 表格 ─── */
89: .table-wrap{overflow-x:auto;}
90: table{width:100%;border-collapse:collapse;font-size:.88rem;}
91: th{background:#f5f7fa;color:var(--text-light);font-weight:600;padding:10px 14px;text-align:left;border-bottom:2px solid var(--border);}
92: td{padding:10px 14px;border-bottom:1px solid #f0f0f0;vertical-align:middle;}
93: tr:hover td{background:#fafbff;}
94: .badge{display:inline-block;padding:2px 10px;border-radius:20px;font-size:.75rem;font-weight:600;}
95: .badge-blue{background:#e3f2fd;color:#1565c0;}
96: .badge-green{background:#e8f5e9;color:#2e7d32;}
97: .badge-orange{background:#fff3e0;color:#e65100;}
98: .badge-red{background:#ffebee;color:#c62828;}
99: .badge-gray{background:#f5f5f5;color:#757575;}
100: .badge-purple{background:#f3e5f5;color:#6a1b9a;}
101: /* 每日答题模式切换 tab */
102: .dq-tab-btn{transition:all .15s;}
103: .dq-tab-btn.active{background:#2563eb!important;color:#fff!important;border-color:#2563eb!important;}
104: 
105: /* ─── 模态框 ─── */
106: .modal-overlay{position:fixed;inset:0;background:rgba(0,0,0,.5);display:flex;align-items:center;justify-content:center;z-index:1000;opacity:0;pointer-events:none;transition:opacity .2s;}
107: .modal-overlay.show{opacity:1;pointer-events:all;}
108: .modal{background:#fff;border-radius:14px;padding:28px;width:560px;max-width:95vw;max-height:90vh;overflow-y:auto;transform:scale(.95);transition:transform .2s;box-shadow:0 20px 60px rgba(0,0,0,.2);}
109: .modal-overlay.show .modal{transform:scale(1);}
110: .modal-header{display:flex;align-items:center;justify-content:space-between;margin-bottom:20px;}
111: .modal-header h3{font-size:1.1rem;font-weight:700;color:var(--primary-dark);}
112: .modal-close{background:none;border:none;font-size:1.4rem;cursor:pointer;color:var(--text-light);line-height:1;}
113: .modal-footer{display:flex;justify-content:flex-end;gap:10px;margin-top:20px;}
114: 
115: /* ─── 文件上传区 ─── */
116: .upload-zone{border:2px dashed var(--border);border-radius:10px;padding:32px;text-align:center;cursor:pointer;transition:all .2s;position:relative;}
117: .upload-zone:hover,.upload-zone.dragover{border-color:var(--primary);background:#f0f7ff;}
118: .upload-zone input{position:absolute;inset:0;opacity:0;cursor:pointer;}
119: .upload-zone .icon{font-size:2.5rem;margin-bottom:10px;}
120: .upload-zone p{color:var(--text-light);font-size:.9rem;}
121: .file-list{margin-top:12px;display:flex;flex-direction:column;gap:8px;}
122: .file-item{display:flex;align-items:center;gap:10px;background:#f8f9fa;border-radius:8px;padding:10px 14px;}
123: .file-item .file-icon{font-size:1.3rem;}
124: .file-item .file-name{flex:1;font-size:.85rem;color:var(--text);overflow:hidden;text-overflow:ellipsis;white-space:nowrap;}
125: .file-item .file-size{font-size:.75rem;color:var(--text-light);}
126: .progress{height:4px;background:#e0e0e0;border-radius:2px;margin-top:4px;overflow:hidden;}
127: .progress-bar{height:100%;background:var(--primary);border-radius:2px;transition:width .3s;}
128: 
129: /* ─── 树形章节 ─── */
130: .tree{list-style:none;}
131: .tree-node{margin:2px 0;}
132: .tree-header{display:flex;align-items:center;gap:8px;padding:8px 12px;border-radius:8px;cursor:pointer;transition:background .2s;}
133: .tree-header:hover{background:#f0f4f8;}
134: .tree-header.active{background:#e3f2fd;color:var(--primary);}
135: .tree-toggle{width:18px;text-align:center;font-size:.8rem;color:var(--text-light);}
136: .tree-label{flex:1;font-size:.9rem;}
137: .tree-actions{display:flex;gap:4px;opacity:0;transition:opacity .2s;}
138: .tree-header:hover .tree-actions{opacity:1;}
139: .tree-children{padding-left:24px;border-left:2px solid #e0e0e0;margin-left:16px;}
140: 
141: /* ─── 题目卡片 ─── */
142: .q-card{border:1px solid var(--border);border-radius:8px;padding:14px;margin-bottom:10px;transition:box-shadow .2s;}
143: .q-card:hover{box-shadow:0 2px 12px rgba(0,0,0,.1);}
144: .q-card-header{display:flex;align-items:flex-start;gap:10px;}
145: .q-no{background:var(--primary);color:#fff;border-radius:50%;width:26px;height:26px;display:flex;align-items:center;justify-content:center;font-size:.78rem;font-weight:700;flex-shrink:0;}
146: .q-text{flex:1;font-size:.9rem;line-height:1.6;}
147: .q-options{margin:10px 0 0 36px;display:flex;flex-direction:column;gap:4px;}
148: .q-option{font-size:.85rem;color:var(--text-light);display:flex;gap:8px;}
149: .q-option.correct{color:var(--success);font-weight:600;}
150: .q-answer{margin:10px 0 0 36px;font-size:.85rem;color:var(--success);}
151: 
152: /* ─── 进度条（得分率） ─── */
153: .rate-bar{display:flex;align-items:center;gap:10px;}
154: .rate-bar .bar{flex:1;height:8px;background:#e0e0e0;border-radius:4px;overflow:hidden;}
155: .rate-bar .fill{height:100%;border-radius:4px;background:var(--primary);}
156: .rate-bar .fill.low{background:var(--danger);}
157: .rate-bar .fill.mid{background:var(--warning);}
158: .rate-bar .pct{min-width:36px;font-size:.8rem;color:var(--text-light);text-align:right;}
159: 
160: /* ─── 标签 ─── */
161: .tabs{display:flex;gap:4px;background:#f0f4f8;border-radius:8px;padding:4px;margin-bottom:20px;}
162: .tab{padding:7px 20px;border-radius:6px;cursor:pointer;font-size:.88rem;transition:all .2s;color:var(--text-light);font-weight:500;}
163: .tab.active{background:#fff;color:var(--primary);box-shadow:var(--shadow);}
164: 
165: /* ─── 搜索框 ─── */
166: .search-box{display:flex;align-items:center;gap:8px;background:#f5f7fa;border:1px solid var(--border);border-radius:8px;padding:0 12px;}
167: .search-box input{border:none;background:transparent;padding:8px 0;outline:none;font-family:inherit;font-size:.88rem;flex:1;}
168: .search-box .icon{color:var(--text-light);}
169: 
170: /* ─── 工具提示 ─── */
171: .tooltip{position:relative;}
172: .tooltip:hover::after{content:attr(data-tip);position:absolute;bottom:calc(100% + 8px);left:50%;transform:translateX(-50%);background:#333;color:#fff;padding:4px 10px;border-radius:4px;font-size:.75rem;white-space:nowrap;pointer-events:none;}
173: 
174: /* ─── 通知 ─── */
175: #toast{position:fixed;top:20px;right:20px;z-index:9999;display:flex;flex-direction:column;gap:8px;}
176: .toast-item{background:#333;color:#fff;padding:12px 20px;border-radius:8px;box-shadow:0 4px 16px rgba(0,0,0,.2);animation:slideIn .3s ease;font-size:.88rem;}
177: .toast-item.success{background:#2e7d32;}
178: .toast-item.error{background:#c62828;}
179: .toast-item.warning{background:#e65100;}
180: @keyframes slideIn{from{transform:translateX(60px);opacity:0;}to{transform:translateX(0);opacity:1;}}
181: 
182: /* ─── 空状态 ─── */
183: .empty{text-align:center;padding:48px 20px;color:var(--text-light);}
184: .empty .icon{font-size:3rem;margin-bottom:12px;}
185: .empty p{font-size:.9rem;}
186: 
187: /* ─── 隐藏面板 ─── */
188: .panel{display:none;}
189: .panel.active{display:block;}
190: 
191: /* ─── 响应式 ─── */
192: @media(max-width:900px){
193:   .sidebar{width:60px;min-width:60px;}
194:   .sidebar-logo p,.nav-item span,.back-home a span,.sidebar-logo h2{display:none;}
195:   .nav-item{justify-content:center;padding:14px;}
196:   .nav-item .icon{margin:0;}
197:   .grid-4,.grid-3{grid-template-columns:1fr 1fr;}
198:   .grid-2{grid-template-columns:1fr;}
199: }
200: 
201: /* ─── 积分徽章 ─── */
202: .points-badge{display:inline-flex;align-items:center;gap:4px;background:linear-gradient(135deg,#f57f17,#ffa000);color:#fff;border-radius:20px;padding:3px 12px;font-size:.8rem;font-weight:700;}
203: .avatar{width:36px;height:36px;border-radius:50%;background:linear-gradient(135deg,var(--primary),var(--primary-light));color:#fff;display:flex;align-items:center;justify-content:center;font-weight:700;font-size:.9rem;flex-shrink:0;}
204: 
205: /* 课程树容器 */
206: .course-panel{display:flex;gap:20px;height:calc(100vh - 200px);}
207: .course-tree-col{width:280px;min-width:280px;overflow-y:auto;}
208: .course-detail-col{flex:1;overflow-y:auto;}
209: 
210: /* ─── 选择题选项行 ─── */
211: .option-row{display:flex;gap:8px;align-items:center;margin-bottom:8px;}
212: .option-row .opt-label{font-weight:700;color:var(--primary);width:24px;flex-shrink:0;}
213: 
214: /* ─── 登录界面 ─── */
215: #loginScreen{
216:   position:fixed;inset:0;
217:   background:linear-gradient(135deg,#0d47a1 0%,#1976d2 50%,#42a5f5 100%);
218:   display:flex;align-items:center;justify-content:center;
219:   z-index:9999;
220:   min-height:100vh;
221:   width:100vw;
222: }
223: .login-box{
224:   background:#fff;
225:   border-radius:16px;
226:   padding:48px 48px 40px;
227:   width:380px;
228:   max-width:90vw;
229:   box-shadow:0 24px 64px rgba(0,0,0,.35);
230:   text-align:center;
231:   position:relative;
232:   top:0;
233:   transform:none;
234: }
235: .login-box h2{color:#0d47a1;font-size:1.6rem;margin-bottom:8px;font-weight:700;}
236: .login-box p{color:#666;font-size:.875rem;margin-bottom:32px;}
237: .login-box input{
238:   width:100%;padding:14px 16px;
239:   border:1.5px solid #ddd;
240:   border-radius:8px;font-size:1rem;
241:   margin-bottom:16px;outline:none;
242:   transition:border-color .2s,box-shadow .2s;
243:   box-sizing:border-box;
244: }
245: .login-box input:focus{border-color:#1565c0;box-shadow:0 0 0 3px rgba(21,101,192,.12);}
246: .login-box button{
247:   width:100%;padding:14px;
248:   background:#1565c0;color:#fff;
249:   border:none;border-radius:8px;
250:   font-size:1rem;font-weight:600;
251:   cursor:pointer;transition:background .2s,transform .1s;
252:   margin-top:4px;
253: }
254: .login-box button:hover{background:#0d47a1;}
255: .login-box button:active{transform:scale(.98);}
256: .login-box .error{color:#c62828;font-size:.85rem;margin-top:14px;min-height:20px;}
257: .login-logo{font-size:3.5rem;margin-bottom:16px;line-height:1;}
258: .main-content{display:none;}
259: .main-content.show{display:flex;flex:1;overflow:hidden;}
260:   /* ═══ 课堂点名（rc- 前缀，深色投屏风格） ═══ */
261:   .rc-classbar{display:flex;align-items:center;gap:10px;background:#fff;border:1px solid #e2e8f0;border-radius:12px;padding:12px 18px;margin-bottom:14px;flex-wrap:wrap;}
262:   .rc-classbar label{font-size:.85rem;color:#64748b;white-space:nowrap;}
263:   .rc-classbar select{padding:7px 12px;border:1px solid #cbd5e1;border-radius:8px;font-size:.9rem;background:#fff;cursor:pointer;outline:none;}
264:   .rc-classbar select:focus{border-color:#2563eb;}
265:   .rc-count{font-size:.8rem;color:#94a3b8;margin-left:auto;}
266:   .rc-progress{height:6px;background:#e2e8f0;border-radius:3px;margin-bottom:14px;overflow:hidden;}
267:   .rc-progress>div{height:100%;background:linear-gradient(90deg,#f59e0b,#f0c96a);border-radius:3px;transition:width .3s;}
268:   .rc-stage{background:#0f1923;border:1px solid #2a3a50;border-radius:20px;padding:34px 24px;text-align:center;min-height:250px;display:flex;flex-direction:column;align-items:center;justify-content:center;position:relative;margin-bottom:14px;user-select:none;}
269:   .rc-idle{font-size:.95rem;color:#4b5563;}
270:   .rc-rolling{font-size:64px;font-weight:500;letter-spacing:6px;color:#f0c96a;min-height:84px;display:flex;align-items:center;justify-content:center;transition:opacity .05s;}
271:   .rc-rolling.fast{opacity:.7;}
272:   .rc-name{font-size:58px;font-weight:500;color:#f0c96a;letter-spacing:4px;animation:rcPop .3s ease;}
273:   .rc-meta{font-size:.85rem;color:#9ca3af;margin-top:10px;}
274:   .rc-meta span{margin:0 8px;}
275:   .rc-badge{display:inline-block;background:#1f3a28;color:#4ade80;border:1px solid #22c55e;border-radius:20px;padding:2px 14px;font-size:.8rem;margin-top:8px;}
276:   @keyframes rcPop{from{transform:scale(.7);opacity:0;}to{transform:scale(1);opacity:1;}}
277:   .rc-done{font-size:1.15rem;color:#22c55e;animation:rcPop .3s ease;}
278:   .rc-ptsrow{display:flex;align-items:center;gap:10px;justify-content:center;margin-bottom:14px;}
279:   .rc-ptsrow label{font-size:.85rem;color:#64748b;}
280:   .rc-ptsrow input[type="number"]{width:84px;text-align:center;padding:7px 10px;border:1px solid #cbd5e1;border-radius:8px;font-size:.95rem;color:#b45309;font-weight:600;outline:none;}
281:   .rc-ptsrow input[type="number"]:focus{border-color:#f59e0b;}
282:   .rc-btngroup{display:flex;gap:12px;justify-content:center;flex-wrap:wrap;margin-bottom:16px;}
283:   .rc-btn{padding:12px 26px;border-radius:10px;font-size:.95rem;font-weight:600;cursor:pointer;border:none;outline:none;transition:opacity .15s,transform .1s;letter-spacing:1px;}
284:   .rc-btn:active{transform:scale(.97);}
285:   .rc-btn:disabled{opacity:.35;cursor:not-allowed;transform:none;}
286:   .rc-btn-start{background:#f0c96a;color:#0f1923;min-width:180px;}
287:   .rc-btn-add{background:#22c55e;color:#fff;min-width:150px;}
288:   .rc-btn-skip{background:#374151;color:#e8eaf0;min-width:120px;}
289:   .rc-btn-ghost{background:#f1f5f9;color:#475569;border:1px solid #cbd5e1;padding:7px 14px;font-size:.8rem;border-radius:8px;}
290:   .rc-bottom{display:flex;gap:14px;}
291:   .rc-box{flex:1;background:#fff;border:1px solid #e2e8f0;border-radius:12px;padding:12px 14px;min-width:0;}
292:   .rc-box-title{font-size:.75rem;color:#94a3b8;letter-spacing:1px;margin-bottom:8px;}
293:   .rc-history{list-style:none;max-height:200px;overflow-y:auto;margin:0;padding:0;}
294:   .rc-history li{display:flex;justify-content:space-between;align-items:center;padding:6px 0;border-bottom:1px solid #f1f5f9;font-size:.85rem;}
295:   .rc-history li:last-child{border-bottom:none;}
296:   .rc-history .hi-pts{color:#16a34a;font-size:.78rem;}
297:   .rc-history .hi-none{color:#94a3b8;font-size:.78rem;}
298:   .rc-remainwrap{max-height:200px;overflow-y:auto;}
299:   .rc-remain{display:inline-block;background:#f8fafc;border:1px solid #e2e8f0;color:#475569;border-radius:6px;padding:3px 9px;font-size:.78rem;margin:3px;}
300:   .rc-empty{font-size:.78rem;color:#cbd5e1;}
301:   @media (max-width:800px){.rc-bottom{flex-direction:column;}}
302: 
